return {["fb12_01"]={["down"]=[[fb12_15]],["dsc"]=[[你简直走进了一片红色的世界，高低左右地垂着各式各样的红绸绫缎彩纸贴花，细细看去，每一处竟都绣扎着鸳鸯凤凰，透出一股股浓郁的喜庆气氛，当中一块横匾:千里姻缘一线牵。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb12_01]],["item1"]=[[bfitem1]],["left"]=[[fb12_09]],["name"]=[[姻缘堂]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb12_02"]={["down"]=[[fb12_12]],["dsc"]=[[方圆数百里内，迎宾楼的名气可谓是不小。来此落脚的名士雅客也为其题匾作诗，流下不少令其得意的东西。楼下布置简易，顾客多是匆匆的行人，买点包子，鸡腿、米酒就赶路去了。楼上是专门举办备类婚宴的喜福堂。]],["id"]=[[fb12_02]],["item1"]=[[cdpd1]],["name"]=[[迎宾楼]],["permission"]=2,["right"]=[[fb12_03]],["role1"]=[[fb12r02_1]],["role2"]=[[fb12r02_2]],["role3"]=[[fb12r02_100]],["role4"]=[[fb12r02_101]],["roomBgm"]=[[chalou]],["roomBgmRule"]=1,["stepMusic"]=[[jiaobu]]},["fb12_03"]={["dsc"]=[[这里已经进入汝州地界了。小镇不大，但是位于中原驿道旁，南珲北往的客人便使得这里慢慢繁荣起来了。甚至使得这里的本地人口甚少，到处都是行色匆匆的江湖客人。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb12_03]],["item1"]=[[fb12item18]],["left"]=[[fb12_02]],["name"]=[[汝州小镇]],["permission"]=1,["right"]=[[fb12_16]],["role1"]=[[fb12r03_1]],["role2"]=[[fb12r03_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb12_06]]},["fb12_04"]={["dsc"]=[[这里是汝州的西城门。从这里是通向西域去的必经要道，一旦有大案发生或是战事起来，立即会在此设卡盘查，平时，官兵也懒得过来多事，城门下一片太平盛世景象。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb12_04]],["item1"]=[[rzdj9]],["name"]=[[汝州西门]],["permission"]=1,["right"]=[[fb12_05]],["role1"]=[[fb12r04_1]],["stepMusic"]=[[jiaobu]]},["fb12_05"]={["dsc"]=[[望西路上望西归，自此出汝州的西城门，便是踏上西去汉中，远征西北的大路了。北面就是汝州城的知府衙门，虽然未经什么修缮，但是略略掉漆的红木白墙却显现出一番更加威严肃穆的感觉。东去是汝州城中心，这里也没有什么店铺。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb12_05]],["item1"]=[[ssyrwdj]],["left"]=[[fb12_04]],["name"]=[[望西路]],["permission"]=1,["right"]=[[fb12_06]],["role1"]=[[fb12r05_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb12_10]]},["fb12_06"]={["down"]=[[fb12_03]],["dsc"]=[[汝州城是本府的大城，历来是兵家必争之地。故州治在此驻扎重兵，盘查南来北往的行人，并负责翦灭附近山上的草寇。由于这里是北上京城的必经之道，官兵盘查也十分严格。从这里向西出城门，可以到五岳之中的嵩山了。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb12_06]],["left"]=[[fb12_05]],["name"]=[[汝州城]],["permission"]=1,["right"]=[[fb12_07]],["role1"]=[[fb12r06_1]],["role2"]=[[fb12r06_2]],["stepMusic"]=[[jiaobu]]},["fb12_07"]={["dsc"]=[[眼前是一座气势雄伟的大庄庭，门廊高大、朱墙黄瓦，竟有些与皇宫相似的味道，只是大门两边立的不是麒麟、狮兽，而是笑眯眯的喜财童子童女，而且大门敞开，任人随意进入，正中上面一块巨大的乌木匾牌红娘庄。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb12_07]],["left"]=[[fb12_06]],["name"]=[[红娘庄大门]],["permission"]=1,["right"]=[[fb12_08]],["role1"]=[[fb12r07_1]],["role2"]=[[fb12r07_2]],["stepMusic"]=[[jiaobu]]},["fb12_08"]={["down"]=[[fb12_13]],["dsc"]=[[走廊两边是红漆金粉的廊柱雕栏，高低错落地挑着两排红灯笼。地上铺着厚厚的大红地毯，急待结婚的新人们进来踩在上面，一股喜庆幸福之感自心底油然而生。前面是一个不大的门厅。]],["id"]=[[fb12_08]],["left"]=[[fb12_07]],["name"]=[[红娘庄走廊]],["permission"]=1,["right"]=[[fb12_09]],["role1"]=[[fb12r08_1]],["stepMusic"]=[[jiaobu]]},["fb12_09"]={["down"]=[[fb12_14]],["dsc"]=[[这里就是天下夫妇定约结缘的红娘堂，只有在这里缔结婚约或是解除婚约才能得到世人的承认。这里是一个不大的门厅，但是经过一番修整之后，显得十分地气派。厅堂正中挂着一块雕着字的乌木匾牌。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb12_09]],["item1"]=[[fb12item3]],["left"]=[[fb12_08]],["name"]=[[红娘堂]],["permission"]=1,["right"]=[[fb12_01]],["role1"]=[[fb12r09_1]],["role2"]=[[fb12r09_2]],["stepMusic"]=[[jiaobu]]},["fb12_10"]={["down"]=[[fb12_05]],["dsc"]=[[这里便是汝州重镇的衙门大门，朱木大柱，青瓦白墙，异常醒目。铜皮大门两边摆动放着两头张牙舞爪的石狮子。前面照例都有一个大鼓，显然是供小民鸣冤用的。直看到去就可以看到知府坐镇的大堂。]],["id"]=[[fb12_10]],["name"]=[[汝州府衙]],["permission"]=1,["role1"]=[[fb12r10_1]],["role2"]=[[fb12r10_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb12_11]]},["fb12_11"]={["down"]=[[fb12_10]],["dsc"]=[[正中一面明镜高悬的大匾，是各地的衙门必备的家当。大堂的地上擦得逞亮却隐约能看到一点点的血痕，看来是大堂用刑时留下的痕迹。两边各各一些肃静、回避的牌子，竟有些不威自怒的感觉。]],["id"]=[[fb12_11]],["name"]=[[知府大堂]],["permission"]=1,["role1"]=[[fb12r11_1]],["role2"]=[[fb12r11_100]],["stepMusic"]=[[jiaobu]]},["fb12_12"]={["dsc"]=[[这里是迎宾楼的二楼，宽敞地可以摆下三十多张八仙桌，正中挂着大大的红色喜字，由于常常有人在此举办婚宴，这里的红烛也就长明，地上铺着厚厚的大红地毯，一派喜气洋洋的景象。你站在楼上眺望，可看见碧波湖水，崇山峻岭。]],["fightBackground"]=[[城镇室内]],["id"]=[[fb12_12]],["item1"]=[[cdpd2]],["name"]=[[喜福堂]],["permission"]=2,["role1"]=[[fb12r12_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb12_02]]},["fb12_13"]={["dsc"]=[[这是一个摆放酒席的偏院，地方足够宽敞，且宾客众多，大家一起互相敬酒吃菜，其乐融融。]],["id"]=[[fb12_13]],["item1"]=[[fb12item3]],["name"]=[[偏院]],["permission"]=2,["role1"]=[[fb12r13_1]],["role2"]=[[fb12r13_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb12_08]]},["fb12_14"]={["dsc"]=[[这是一个摆放酒席的偏院，地方足够宽敞，且宾客众多，大家一起互相敬酒吃菜，其乐融融。]],["id"]=[[fb12_14]],["item1"]=[[fb12item4]],["name"]=[[偏院]],["permission"]=2,["role1"]=[[fb12r14_1]],["role2"]=[[fb12r14_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb12_09]]},["fb12_15"]={["dsc"]=[[这是一个摆放酒席的偏院，地方足够宽敞，且宾客众多，大家一起互相敬酒吃菜，其乐融融。]],["id"]=[[fb12_15]],["item1"]=[[fb12item5]],["name"]=[[偏院]],["permission"]=2,["role1"]=[[fb12r15_1]],["role2"]=[[znq3chfc1]],["role3"]=[[znq3chfc2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb12_01]]},["fb12_16"]={["dsc"]=[[典雅的小竹楼，一个瘦弱的书生正若无旁人的拨弄着琴弦。]],["id"]=[[fb12_16]],["item1"]=[[lylitem1]],["item2"]=[[cg2item1]],["left"]=[[fb12_03]],["name"]=[[竹乐斋]],["permission"]=2,["role1"]=[[QX2R16_1]],["role2"]=[[2019qxcdg1a]],["role3"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]]},["fb12_17"]={["down"]=[[fb12_04]],["dsc"]=[[暗道漆黑一片，墙壁上的微弱的烛火仅能照明三步之内的土石路，不知从何处还传来水滴之声。]],["id"]=[[fb12_17]],["name"]=[[暗道]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb12_18]]},["fb12_18"]={["down"]=[[fb12_17]],["dsc"]=[[仓库里堆放着许多漆红木箱，墙壁上新凿的痕迹可以看得出修建时匆忙，顶上不时渗漏几滴地下积水，根本不适合储存物资。]],["id"]=[[fb12_18]],["item1"]=[[rzdj7]],["item2"]=[[rzdj6]],["name"]=[[仓库]],["permission"]=2,["stepMusic"]=[[jiaobu]]}}0000000000